import{z as i,x as d,o as A,c as s,q as l,j as n,D as t,d as e,s as r,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"文本因子的深化","description":"","frontmatter":{"title":"文本因子的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-text-deep.md","filePath":"quant/alt-text-deep.md","lastUpdated":1791413859000}'),p={name:"quant/alt-text-deep.md"};function C(m,E,u,D,h,F){const B=d("Mermaid");return A(),s("div",null,[E[2]||(E[2]=l('<h1 id="文本因子的深化" tabindex="-1">文本因子的深化 <a class="header-anchor" href="#文本因子的深化" aria-label="Permalink to &quot;文本因子的深化&quot;">​</a></h1><div class="epigraph"><p>文本因子深化的单位不是把模型换大，而是每换一级表征都要付一次增量证据：新的分数必须解释旧的分数解释不了的那部分收益。</p><footer>—— 据 Loughran and McDonald, Journal of Finance, 2011；Ke, Kelly and Xiu, 2019 整理</footer></div><p><a href="/quant/dp-map">上一课</a>把深度定价收在管线上：数据窗口、表示、损失、模拟器与种子都是模型的一部分，基线先于架构、测度先于用途、验证先于部署，并让下一门课程带着这套管线口径走进另类数据。本课是「另类数据工程」的第一课。主干课给出的是「一份语料、一个词典、一个 IC」的单点做法；深化是把文本从单一分数升级为<strong>表征阶梯</strong>，并为每次升级建立相对上一级的验收。后课默认你手上的文本已经切成带双时间戳的文档-证券对。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口在两端。测量端：词典把整份文档压成一个数，年报里 MD&amp;A 措辞的逐年变化、脚注里风险条目的增删、问答里的回避与含混，全被压没了——这些恰恰是市场慢消化的部分。评价端：换一个更大的语言模型重跑，IC 变好了，但没人能回答「好出来的部分」是新的信息，还是同一条情绪信息的再包装；更没人回答为了这个数字试了多少个模型与提示词——<a href="/quant/backtest-overfitting">回测过拟合</a>的折价账没有人记。缺口因此不是「更强的文本模型」，而是<strong>表征升级的验收协议</strong>。</p><p><span class="marginnote">「词典法」就是查表打分：预备一份标注正负的词表，数一数文档里正面词与负面词各出现多少次，差值就是情绪分。它透明、便宜、可复现，代价是把整份年报压成一个数——语气之外的结构信息（在哪里说的、说得多隐晦）全部丢失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表征分四级，逐级付费：词典是 \\(L_1\\) 基线；主题模型（Blei, Ng and Jordan, 2003）把文档放进话题空间是 \\(L_2\\)；有监督嵌入把文本当高维协变量、用正则约束（Ke, Kelly and Xiu, 2019；Gentzkow, Kelly and Taddy, 2019）是 \\(L_3\\)；大模型表征与打分是 \\(L_4\\)。升级判据只有一条：把新表征对旧表征与盈余惊喜回归取残差，残差对未来收益的预测若不显著，就停在上一级。三条纪律逐字沿用主干：事件时间与可得时间分开，<a href="/quant/point-in-time">点时基本面</a>的规则按列执行；标签窗口对齐<a href="/quant/label-horizon-overlap">标签与持仓期</a>的重叠规则；持有期对齐信号的半衰期，文本因子衰减快，错配的持有期会把 alpha 磨成手续费。</p><p><span class="marginnote">「半衰期」借自放射性：信息优势衰减到一半所用的时间。设某文本信号的半衰期约一周，而你的持有期是一个月，那么持有期末只剩约 6% 的优势（0.5 的 4 次方），大概率不够覆盖费用——持有期与半衰期错配，就是这么把 alpha 磨成手续费的。</span></p>',9)),(A(),n(o,null,{default:t(()=>[r(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E6%96%87%E6%A1%A3-%E8%AF%81%E5%88%B8%E5%AF%B9%EF%BC%9A%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%E5%8A%A0%E5%8F%AF%E5%BE%97%E6%97%B6%E9%97%B4%22%5D%20--%3E%20L1%5B%22L1%20%E8%AF%8D%E5%85%B8%E5%88%86%EF%BC%9A%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20L1%20--%3E%20G1%7B%22%E6%AE%8B%E5%B7%AE%20IC%20%E6%98%BE%E8%91%97%EF%BC%9F%22%7D%0A%20%20G1%20--%3E%7C%E6%98%AF%7C%20L2%5B%22L2%20%E4%B8%BB%E9%A2%98%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20L2%20--%3E%20G2%7B%22%E6%AE%8B%E5%B7%AE%20IC%20%E6%98%BE%E8%91%97%EF%BC%9F%22%7D%0A%20%20G2%20--%3E%7C%E6%98%AF%7C%20L3%5B%22L3%20%E6%9C%89%E7%9B%91%E7%9D%A3%E5%B5%8C%E5%85%A5%22%5D%0A%20%20L3%20--%3E%20G3%7B%22%E6%AE%8B%E5%B7%AE%20IC%20%E6%98%BE%E8%91%97%EF%BC%9F%22%7D%0A%20%20G3%20--%3E%7C%E6%98%AF%7C%20L4%5B%22L4%20%E5%A4%A7%E6%A8%A1%E5%9E%8B%E8%A1%A8%E5%BE%81%22%5D%0A%20%20G1%20--%3E%7C%E5%90%A6%7C%20K1%5B%22%E5%81%9C%E5%9C%A8%E8%AF%8D%E5%85%B8%E7%BA%A7%22%5D%0A%20%20G2%20--%3E%7C%E5%90%A6%7C%20K2%5B%22%E5%81%9C%E5%9C%A8%E4%B8%8A%E4%B8%80%E7%BA%A7%22%5D%0A%20%20G3%20--%3E%7C%E5%90%A6%7C%20K3%5B%22%E5%81%9C%E5%9C%A8%E4%B8%8A%E4%B8%80%E7%BA%A7%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("深化有上限，原因是文档级情绪的大头是已定价的基本面新闻，主干课已经演示过这条地板。真正的增量住在难消化的文本里：年报可读性的恶化与盈余持续性的关系（Li, 2008）、脚注与风险披露的边际变化，这类内容的处理成本低、被读到的比例小。语言模型降低的是"),a("strong",null,"特征工程成本"),e("，不是测量误差：提示词会把词典偏置原样带回来，打分与词典分高相关；幻觉会制造语料里不存在的句子；试过的每个提示与模型都要计入 \\(N\\)，按紧缩夏普的口径打折（"),a("a",{href:"/quant/bailey-dsr"},"DSR"),e("）。不这么验收会错在哪：你会把「LLM 复读了词典」当成「发现了新信号」，为再包装付溢价。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},'Loughran–McDonald（2011）的出发点是一个可数的错配：通用情感词典的负面清单里，近四分之三的词在财务叙述里并不负面——"liability""capital" 这类词按通用清单打分会把中性描述算成坏消息。表征再深，这道错分仍是基线。')],-1)),E[6]||(E[6]=a("p",null,"残差增量验收的分解路径——回答「新模型分数是增量还是复读」：",-1)),(A(),n(o,null,{default:t(()=>[r(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20NEW%5B%22%E6%96%B0%E8%A1%A8%E5%BE%81%E5%88%86%E6%95%B0%22%5D%20--%3E%20REG%5B%22%E5%AF%B9%E6%97%A7%E5%88%86%E6%95%B0%E4%B8%8E%E7%9B%88%E4%BD%99%E6%83%8A%E5%96%9C%E5%9B%9E%E5%BD%92%22%5D%0A%20%20OLD%5B%22%E4%B8%8A%E4%B8%80%E7%BA%A7%E8%A1%A8%E5%BE%81%E5%88%86%E6%95%B0%22%5D%20--%3E%20REG%0A%20%20SE%5B%22%E7%9B%88%E4%BD%99%E6%83%8A%E5%96%9C%22%5D%20--%3E%20REG%0A%20%20REG%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%EF%BC%9A%E6%97%A7%E5%88%86%E6%95%B0%E8%A7%A3%E9%87%8A%E4%B8%8D%E4%BA%86%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A%20%20RES%20--%3E%20T%7B%22%E6%AE%8B%E5%B7%AE%20IC%20%E6%98%BE%E8%91%97%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E6%98%AF%22%7C%20UP%5B%22%E5%A2%9E%E9%87%8F%E7%9C%9F%E5%AE%9E%EF%BC%9A%E5%8D%87%E7%BA%A7%E5%88%B0%E6%96%B0%E8%A1%A8%E5%BE%81%22%5D%0A%20%20T%20--%3E%7C%22%E5%90%A6%22%7C%20STAY%5B%22%E5%A4%8D%E8%AF%BB%E4%B8%8E%E5%86%8D%E5%8C%85%E8%A3%85%EF%BC%9A%E5%81%9C%E5%9C%A8%E4%B8%8A%E4%B8%80%E7%BA%A7%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理文本之间的<strong>关系</strong>——把文档相似度变成公司之间的边是下一课的对象；爬虫的合规与工程归工程单元；地理与卡数据各有其课。也不宣称语言模型必有 alpha：它的产出同样要过残差增量这道门。供应商语料的再分发与留存限制（<a href="/quant/web-data-compliance">网络数据合规</a>）会约束特征的可移植性，续约即模型风险，这在采购时就要入账。</p><p><span class="marginnote">常见误区：「模型越大，文本因子越强」。更大的模型往往只是更贵、更会顺着提示词说话，分数与词典的相关反而可能更高。判断升级的唯一标准是残差增量——新分数能否显著解释旧分数解释不了的那部分收益，与参数量无关。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深化的形式是表征阶梯：词典、主题、有监督嵌入、大模型，每级只凭残差增量升级。</li><li>增量的对手方是上一级表征加盈余惊喜，不是零基准。</li><li>语言模型省的是特征工程，不省测量误差；试过的每个配置都计入 \\(N\\) 并打折。</li><li>文本因子的半衰期短，标签与持有期必须对齐，否则只留下换手。</li><li>出处：Tetlock, <em>JF</em>, 2007；Loughran and McDonald, <em>JF</em>, 2011；Blei, Ng and Jordan, <em>JMLR</em>, 2003；Li, <em>JAE</em>, 2008；Gentzkow, Kelly and Taddy, <em>JEL</em>, 2019；Ke, Kelly and Xiu, 2019。</li></ul>',5))])}const _=i(p,[["render",C]]);export{L as __pageData,_ as default};
